// ============================================
// VALIDATION INPUT - Text Generator (BYOT Multi-Provider)
// ============================================

const input = $input.first().json;
const body = input.body || input;
const ctx = body.context || {};

const errors = [];

// --- REQUIRED: provider ---
const provider = (body.provider || ctx.provider || '').toLowerCase();
const validProviders = ['anthropic', 'openai', 'mistral'];
if (!provider) {
  errors.push('provider requis (anthropic, openai, mistral)');
} else if (!validProviders.includes(provider)) {
  errors.push(`provider invalide: ${provider} (doit etre: ${validProviders.join(', ')})`);
}

// --- REQUIRED: model ---
const model = body.model || ctx.model;
if (!model || typeof model !== 'string' || model.trim().length === 0) {
  errors.push('model requis');
}

// --- REQUIRED: api_key (BYOT - NO FALLBACK) ---
const apiKey = body.api_key || ctx.api_key;
if (!apiKey || typeof apiKey !== 'string' || apiKey.trim().length === 0) {
  errors.push('api_key requis (BYOT pattern - aucun fallback sur env)');
}

// --- REQUIRED: prompt ---
const prompt = body.prompt || ctx.prompt;
if (!prompt || typeof prompt !== 'string' || prompt.trim().length === 0) {
  errors.push('prompt requis (chaine non vide)');
}

// --- Context fields for tracing ---
const userId = body.user_id || ctx.user_id || null;
const guildId = body.guild_id || ctx.guild_id || null;
const userRequest = body.user_request || ctx.user_request || null;

// --- Optional parameters ---
const systemPrompt = body.system_prompt || ctx.system_prompt || 'You are a helpful assistant that generates high-quality text based on user instructions.';
const temperature = parseFloat(body.temperature ?? ctx.temperature ?? 0.7);
const maxTokens = parseInt(body.max_tokens || ctx.max_tokens || 2048);

// Validate temperature
if (isNaN(temperature) || temperature < 0 || temperature > 2) {
  errors.push('temperature doit etre entre 0 et 2');
}

// Validate max_tokens
if (isNaN(maxTokens) || maxTokens < 1 || maxTokens > 200000) {
  errors.push('max_tokens doit etre entre 1 et 200000');
}

if (errors.length > 0) {
  return {
    valid: false,
    errors: errors,
    user_id: userId,
    guild_id: guildId,
    user_request: userRequest
  };
}

// Build user content with context
let userContent = prompt.trim();
if (userRequest) {
  userContent = `User context: ${userRequest}\n\n${userContent}`;
}

return {
  valid: true,
  provider: provider,
  model: model.trim(),
  api_key: apiKey.trim(),
  prompt: prompt.trim(),
  user_content: userContent,
  system_prompt: systemPrompt,
  temperature: temperature,
  max_tokens: maxTokens,
  user_id: userId,
  guild_id: guildId,
  user_request: userRequest,
  startTime: Date.now()
};

// ============================================
// BUILD VALIDATION ERROR
// ============================================

const input = $input.first().json;

return {
  success: false,
  _trace: {
    service_response: { validation_errors: input.errors },
    provider: 'none',
    mode: 'error',
    latency_ms: 0,
    user_id: input.user_id,
    guild_id: input.guild_id,
    user_request: input.user_request
  },
  error: {
    code: 'VALIDATION_ERROR',
    message: input.errors.join(', '),
    http_status: 400
  },
  user_id: input.user_id,
  guild_id: input.guild_id,
  user_request: input.user_request
};

